function clean(value, max = 500) {
  return typeof value === 'string' ? value.trim().replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '').slice(0, max) : '';
}

function sanitizeError(value) {
  // Keep the reason, but remove typical credential forms, quoted payloads and URLs.
  return String(value || 'Execution failed; inspect node settings').split('\n')[0]
    .replace(/https?:\/\/\S+/gi, '[URL removed]')
    .replace(/\b(?:Bearer\s+)?eyJ[\w.-]+/g, '[credential removed]')
    .replace(/\b(?:sk-|xox[baprs]-)[\w-]+/g, '[credential removed]')
    .replace(/\b(?:authorization|api[-_ ]?key|token|password|secret)\b\s*[:=]\s*\S+/gi, '[credential removed]')
    .replace(/\{.*|\[.*$/, '[details omitted]')
    .replace(/"[^"]*"|'[^']*'/g, '[quoted value removed]')
    .replace(/\b[A-Za-z0-9_+/=-]{32,}\b/g, '[long value removed]')
    .slice(0, 500);
}
const e=$input.first().json,execution=e.execution||{};
const reason=sanitizeError(execution.error?.message||e.trigger?.error?.message).replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[email omitted]');
return [{json:{execution_id:String(execution.id||''),node:clean(execution.lastNodeExecuted||e.trigger?.error?.node?.name||'Unknown node',160),message:reason,at:new Date().toISOString(),error_channel_id:'<YOUR_SLACK_CHANNEL_ID>'}}];
